-- S294 (SkyCadence), 2026-09-26: Rule 8 ingest - five rows, INSERT-only, idempotent on slug, plus one explicit supersede.
-- Sam's ESL sheet verdicts (verified_by names him), two ESL measurements and a test milestone (verified by merged PR #1704),
-- and the narration procedure (verified by its committed KB note). Summary is one sentence of at most 400 characters
-- (cpl_memory_summary_check); the long text sits in detail; plain is present on every row. The first send failed on that
-- check and wrote nothing. The supersede touches a session-authored row (SkyThread, S208), never a human-sourced one.
-- The log entries are SEPARATE statements (a data-modifying CTE cannot see its own rows).
-- Rollback: delete from cpl_memory_log where actor = 'SkyCadence-s294';
--           delete from cpl_memory where author = 'SkyCadence-s294';
--           update cpl_memory set status = 'proposed', superseded_by = null where slug = 'esl-band-guards-test-the-superseded-dryrun';
insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, source, related, status, verified_by, verified_at, event_date, author)
select x.slug, x.kind, 'cpl', x.title, x.summary, x.detail, x.plain, x.tags, x.source, '{}'::text[], x.status, x.verified_by, now(), date '2026-09-26', 'SkyCadence-s294'
from jsonb_to_recordset($json$[{"slug": "sam-esl-merging-sheet-verdicts-2026-09-26", "kind": "decision", "title": "Sam: the ESL merging sheet, all nine as proposed", "summary": "Sam completed the ESL merging procedure sheet on 2026-09-26 with all nine items taken as proposed and none ruled one by one, so the reader fixes, the health moves, the ladder re-levels his August rulings clear, the transfer three, the new-identity fold and pulling the film course all stand, the nine over-claims stay, and a monthly pass follows.", "detail": "Sheet https://claude.ai/artifact/LaZmu7NYj11DigAEbxsUMS, replies/done at 2026-09-26T19:24Z: 1 fix, 2 move, 3 health, 4 three, 5 fold, 6 apply, 7 leave, 8 monthly, 9 pull (all as proposed). The rule changes shipped in code (#1704). The data changes went to him as one SQL paste (kb/esl_sheet_out/2026-09-26/apply.sql with rollback.sql; cohorts esl-catalog/health/ladder/newfold/transfer-s294@bot, expected 6/18/30/89/3), because the SQL guard keeps kb_curation writes with him and the cross-list precedent holds as-proposed data changes for an explicit go: running the paste is the go. Item 8 is a new standing cadence and waits until the paste lands. Held out of item 5: three new identities (one reads as transfer composition, unruled; two Optical Technician rows carry HLTH member courses).", "plain": "Sam approved every recommendation on the ESL grouping sheet on 26 September. The rule fixes are live in the code. The regrouping itself, about 150 ESL course groups, is ready as one change he runs, with an undo file beside it. The nine groups filed a level higher than their own college's catalog stay where they are, as he decided in August.", "tags": ["esl-packaging", "decision-sheet", "ccr"], "source": "https://claude.ai/artifact/LaZmu7NYj11DigAEbxsUMS (replies/done, 2026-09-26); PR #1704", "status": "verified", "verified_by": "Sam (sheet Complete, 2026-09-26)"}, {"slug": "count-a-sheet-item-after-the-items-that-outrank-it-2026-09-26", "kind": "pitfall", "title": "Count a sheet item after the items that outrank it", "summary": "On the ESL merging sheet, item 2 counted 102 catalog re-levels on its own, but applied after the items that outrank it the count is 6, because the ladder vote keeps 92 at Beginning under Sam's ruling that the statewide standard wins over catalog wording and the health rule claims 4.", "detail": "kb/_esl_sheet_apply_build.py gives each row to the first item that claims it, in precedence order (3, then 6, then 2), and re-measures every count at build time from a fresh read; the sheet's own count is never the apply's. Before counts go on a decision sheet whose items overlap, compute each item's rows after the items that outrank it, or label the count as measured before precedence.", "plain": "A decision sheet said one change would move 102 ESL groups. Once the higher-priority rules Sam had already approved were applied first, only 6 of those groups were left for that change. When several changes touch the same records, count each one after the ones that take priority, or the sheet overstates what will happen.", "tags": ["esl-packaging", "decision-sheet", "methodology", "measurement"], "source": "PR #1704; kb/esl_sheet_out/2026-09-26/plan.json", "status": "verified", "verified_by": "merged PR #1704"}, {"slug": "folding-a-merge-target-resolves-through-the-chain-2026-09-26", "kind": "fact", "title": "Folding a merge target is safe: chains resolve", "summary": "An identity that other identities already merge into can itself be folded into a comprehensive, because flatten_merge_chains in excel_to_dashboard.py follows every source to the end of its chain, and 88 of the 147 identities in the 2026-09-26 ESL paste were such targets, four of them carrying Sam's own June merges.", "detail": "Measured 2026-09-26 by read-only queries (kb/esl_sheet_out/2026-09-26/preflight.json). The overlay then holds two hops (X to Y, Y to Z) and X's courses land in Z. No ESL survivor carries a merge_into row, so no chain can loop; on a cycle the generator keeps the hop the overlay recorded rather than hang. The checks before a fold: no survivor carries a merge_into row of its own, and no pending unified_title_merge_confirm names a touched id or target.", "plain": "If course group A was merged into B in June, and B is now folded into the Beginning ESL group, A's courses follow B into Beginning ESL on their own. None of the earlier merges needs redoing, including the four Sam made himself.", "tags": ["esl-packaging", "merge", "ccr", "kb_curation"], "source": "excel_to_dashboard.py flatten_merge_chains; PR #1704 (kb/esl_sheet_out/2026-09-26/preflight.json)", "status": "verified", "verified_by": "merged PR #1704"}, {"slug": "hear-a-synthetic-voice-through-a-recognizer-2026-09-26", "kind": "procedure", "title": "Check a synthetic narration with a recognizer", "summary": "Before a person hears a synthetic narration, read the tokenizer's phonemes in the sentence, fix at the phoneme level what spelling cannot and make every fix prove it fired, ban the readings the listener rejected, and transcribe the finished read with a local recognizer, which catches misreads the phonemes cannot show.", "detail": "Initialisms read differently alone and in context: Kokoro reads unspaced FTES as the word 'eftess', and EDD alone as 'ed'. faster-whisper (small, local) caught 'the 2627 year' and 'do November first'; its word timings measured CPL at 570 ms unspaced against 702 ms spaced. prototype/funding_video/narrate.py (--check runs the phonemes only), narration_s1.json (phoneme_fixes, never). Wording moves a read more than stress marks do. A recognizer says nothing about warmth or pace, so a person still listens last. Also measure loudness: the narrated mix rendered 5 dB under the music-only cuts until loudnorm at -17 LUFS joined render.sh.", "plain": "Before Sam hears a computer-voiced narration, we play it into speech-recognition software on our own machine and compare what it heard with the script. That catches mispronunciations, such as two years run together, before anyone spends time listening, and it measures whether the voice now says CPL quickly.", "tags": ["video", "narration", "tts", "methodology", "implementation-funding"], "source": "docs/kb-notes/methodology-hear-a-synthetic-voice-through-a-recognizer.md; PRs #1701, #1703", "status": "verified", "verified_by": "committed KB note (PR #1701)"}, {"slug": "esl-ladder-rules-have-their-own-test-2026-09-26", "kind": "fact", "title": "The ESL ladder rules now have a test", "summary": "tests/esl_reader_and_ladder_test.py, in CI since #1704, covers what the ESL ladder script adds to the shared reader: Sam's per-ladder sets with the L=2 row, the noncredit shift, the member vote and its tie, the identity word's precedence, and the purpose carve-out skip.", "detail": "It keeps the pair 'no carve-out was re-banded' and 'carve-outs were seen, so the guard can fire'. The whole-corpus ladder derivation has no assertion yet. Supersedes esl-band-guards-test-the-superseded-dryrun (SkyThread, S208), whose claim that the live ladder script had no test at all held until this suite; the reader guards in tests/esl_relevel_bands_test.py still cover the shared reader, since the ladder script imports it.", "plain": "The rules that sort ESL courses into Beginning, Intermediate and Advanced by each college's own level ladder had no automated check until 26 September. A test now proves them on every change, including that purpose groups such as Civic ESL are never re-sorted by level.", "tags": ["esl-packaging", "tests"], "source": "PR #1704", "status": "verified", "verified_by": "merged PR #1704"}]$json$::jsonb)
  as x(slug text, kind text, title text, summary text, detail text, plain text, tags text[], source text, status text, verified_by text)
where not exists (select 1 from public.cpl_memory m where m.slug = x.slug);
update public.cpl_memory set status = 'superseded', superseded_by = 'esl-ladder-rules-have-their-own-test-2026-09-26'
  where slug = 'esl-band-guards-test-the-superseded-dryrun' and status <> 'superseded';
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyCadence-s294', 'create', 'checkpoint auto-write', to_jsonb(m) from public.cpl_memory m
where m.slug in ('sam-esl-merging-sheet-verdicts-2026-09-26','count-a-sheet-item-after-the-items-that-outrank-it-2026-09-26','folding-a-merge-target-resolves-through-the-chain-2026-09-26','hear-a-synthetic-voice-through-a-recognizer-2026-09-26','esl-ladder-rules-have-their-own-test-2026-09-26')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyCadence-s294', 'supersede', 'status proposed -> superseded: the ESL ladder script got its own test in #1704 (superseded_by esl-ladder-rules-have-their-own-test-2026-09-26)', to_jsonb(m)
from public.cpl_memory m where m.slug = 'esl-band-guards-test-the-superseded-dryrun'
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'supersede' and l.actor = 'SkyCadence-s294');
select m.slug, m.status, m.verified_by, m.plain is not null as has_plain,
       count(l.id) filter (where l.action='create') as creates, count(l.id) filter (where l.action='supersede') as supersedes
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.author = 'SkyCadence-s294' or m.slug = 'esl-band-guards-test-the-superseded-dryrun'
group by m.slug, m.status, m.verified_by, m.plain order by m.slug;

